(function(){ const d = window.DATA.N2; d.questions.push(
    {"t": "reading", "s": "tan", "q": "このお知らせの内容として、正しいものはどれですか。", "o": ["営業時間は変わらず、午後三時に閉まる。", "夜も九時まで開いているが、夜の料理は出るまでに時間がかかる。", "夜は電話で注文した人にしか料理を出さない。", "社員でなくても、飲み物が安くなる。"], "a": 1, "x": "Kafe buka sampai pukul 9 malam, tetapi masakan malam dimasak setelah dipesan sehingga butuh sekitar 20 menit. Diskon hanya untuk pemegang kartu pegawai.", "p": "社員のみなさまへ\n来月から、本社ビルの一階にあるカフェが夜の営業を始めることになりました。これまでは午後三時で閉まっていたため、残業をする人からは「遅い時間に軽い食事ができる場所がほしい」という声が多く寄せられていました。新しい営業時間は午後九時までです。ただし、夜は注文を受けてから調理するため、料理が出るまで二十分ほどかかります。急いでいる方は、前もって電話で注文しておくと便利です。なお、社員証を見せると、飲み物が一割引きになります。"},
    {"t": "reading", "s": "tan", "q": "急いでいる人は、どうするとよいと書いてありますか。", "o": ["前もって電話で注文しておく。", "社員証を見せて割引してもらう。", "午後三時より前に食べに行く。", "料理ができるまで二十分待つ。"], "a": 0, "x": "Teks menyarankan memesan lewat telepon terlebih dahulu bagi yang terburu-buru (前もって電話で注文).", "p": "社員のみなさまへ\n来月から、本社ビルの一階にあるカフェが夜の営業を始めることになりました。これまでは午後三時で閉まっていたため、残業をする人からは「遅い時間に軽い食事ができる場所がほしい」という声が多く寄せられていました。新しい営業時間は午後九時までです。ただし、夜は注文を受けてから調理するため、料理が出るまで二十分ほどかかります。急いでいる方は、前もって電話で注文しておくと便利です。なお、社員証を見せると、飲み物が一割引きになります。"},
    {"t": "reading", "s": "tan", "q": "この制度について、筆者が言いたいことはどれですか。", "o": ["若い人にも商店街にもよい点があるが、成功するかどうかはこれからの努力による。", "家賃が一年間半額になるので、出店すれば必ず成功する。", "商店街の人たちは、この制度に反対している。", "パン屋以外の新しい店は、あまり人気がない。"], "a": 0, "x": "Penulis menyebut manfaat bagi pemuda dan pertokoan, tetapi menutup dengan 'bergantung usaha ke depan'. Sewa setengah harga hanya 3 bulan pertama.", "p": "最近、うちの近所の商店街では、空き店舗を使って「お試し出店」ができる制度が始まった。家賃は最初の三か月だけ半額になり、その間に客の反応を見て、続けるかどうか決められる。店を持ちたいが資金が足りない若い人たちにとっては、失敗した時の損が小さいので、挑戦しやすい仕組みだ。一方、商店街の側にも利点がある。新しい店が増えれば、買い物に来る人も増えるからだ。実際に、先月開いたパン屋には、毎朝行列ができている。ただ、お試し期間が終わった後も続けられるかどうかは、これからの努力次第だろう。"},
    {"t": "reading", "s": "tan", "q": "「お試し出店」で、出店する人にとってよい点は何ですか。", "o": ["お金がなくても、ずっと店を持てる。", "三か月後には家賃が無料になる。", "客が多い商店街だけを選んで出店できる。", "客の反応を見てから続けるか決められ、失敗しても損が小さい。"], "a": 3, "x": "Selama 3 bulan pertama sewa separuh dan bisa menilai reaksi pelanggan, sehingga kerugian jika gagal kecil.", "p": "最近、うちの近所の商店街では、空き店舗を使って「お試し出店」ができる制度が始まった。家賃は最初の三か月だけ半額になり、その間に客の反応を見て、続けるかどうか決められる。店を持ちたいが資金が足りない若い人たちにとっては、失敗した時の損が小さいので、挑戦しやすい仕組みだ。一方、商店街の側にも利点がある。新しい店が増えれば、買い物に来る人も増えるからだ。実際に、先月開いたパン屋には、毎朝行列ができている。ただ、お試し期間が終わった後も続けられるかどうかは、これからの努力次第だろう。"},
    {"t": "reading", "s": "tan", "q": "「私」は今、どうなりましたか。", "o": ["まったく緊張しなくなり、長く話せるようになった。", "相変わらず、会議で意見が言えない。", "緊張はするが、言葉が出なくなることはなくなった。", "先輩の代わりに会議で発表するようになった。"], "a": 2, "x": "'Sekarang pun masih gugup, tetapi tidak lagi kehilangan kata-kata.'", "p": "私は以前、人前で話すのが苦手だった。会議で意見を求められるたびに、頭が真っ白になってしまうのである。そこで、先輩に相談したところ、「うまく話そうと思わず、まず結論だけ一文で言えばいい」と教えてもらった。それ以来、話す前に言いたいことを一文にまとめる練習を続けている。最初のうちは、一文にまとめるのにも時間がかかったが、続けるうちに慣れてきた。今でも緊張はするが、以前のように言葉が出なくなることはなくなった。"},
    {"t": "reading", "s": "tan", "q": "先輩は、どんなことを教えてくれましたか。", "o": ["できるだけ長く、詳しく説明したほうがよいということ。", "まず結論だけを一文で言えばよいということ。", "緊張しないように深呼吸をするということ。", "会議の前に話す内容を全部覚えておくということ。"], "a": 1, "x": "Nasihat senior: jangan berusaha bicara bagus, cukup sampaikan kesimpulan dalam satu kalimat.", "p": "私は以前、人前で話すのが苦手だった。会議で意見を求められるたびに、頭が真っ白になってしまうのである。そこで、先輩に相談したところ、「うまく話そうと思わず、まず結論だけ一文で言えばいい」と教えてもらった。それ以来、話す前に言いたいことを一文にまとめる練習を続けている。最初のうちは、一文にまとめるのにも時間がかかったが、続けるうちに慣れてきた。今でも緊張はするが、以前のように言葉が出なくなることはなくなった。"},
    {"t": "reading", "s": "tan", "q": "工事の期間中について、正しいものはどれですか。", "o": ["本を返す時は、一階の受付に直接持っていかなければならない。", "二階の閲覧室で勉強することができる。", "返却用ポストに入れれば、本を返せる。", "本を借りることはできなくなる。"], "a": 0, "x": "Kotak pengembalian tidak bisa dipakai; buku harus diserahkan langsung ke resepsi lantai 1. Peminjaman tetap bisa.", "p": "図書館からのお知らせ\n来週の月曜日から三日間、館内の工事のため、二階の閲覧室は利用できません。この間、本を借りたり返したりすることは、これまでどおり一階の受付でできます。ただし、返却用ポストは工事のため使えませんので、必ず受付に直接お持ちください。勉強のための席は、一階の多目的ホールに六十席用意します。なお、貸出カードの更新は、工事の期間中も受付で行います。ご迷惑をおかけしますが、ご協力をお願いいたします。"},
    {"t": "reading", "s": "tan", "q": "筆者の考えに合うものはどれですか。", "o": ["忙しい時でも、大切な人への小さな気づかいを忘れないことが大切だ。", "「忙しい」という言葉は、絶対に使ってはいけない。", "忙しい時は、家族との時間が減っても仕方がない。", "忙しいことは、人には言わずに我慢したほうがよい。"], "a": 0, "x": "Menurut penulis, masalahnya bukan mengucapkan 'sibuk', melainkan menomorduakan orang tersayang.", "p": "「忙しい」という言葉は、「心」を「亡くす」と書く。だから使わないほうがいいという話を聞いたことがある。しかし、私は少し違う考えを持っている。忙しいと言うこと自体が悪いのではなく、忙しさを理由にして、家族や友人との時間を後回しにしてしまうことが問題なのだと思う。時間がないと言いながらスマートフォンを見ている自分に、気づくこともある。忙しい時こそ、大切な人に一言メッセージを送るなど、小さな気づかいを忘れたくない。"},
    {"t": "reading", "s": "tan", "q": "筆者がまたこの店で買い物をしたいと思うのは、なぜですか。", "o": ["店のホームページで買うと、いつも安くなるから。", "この店は、どの商品も他の店より安いから。", "店員が希望を聞いて、予算より安い物を買えるよう手伝ってくれたから。", "店員に高い商品を勧められて、満足したから。"], "a": 2, "x": "Pramuniaga menanyakan kebutuhan dengan sopan dan tidak memaksakan barang mahal, sehingga penulis hemat sekitar 10.000 yen.", "p": "先週、駅前の電気店でノートパソコンを買った。店員は、必要な機能を丁寧に聞いてくれて、高い商品を無理に勧めることもなかった。おかげで、予算より一万円ほど安く買うことができた。家に帰ってから、店のホームページで評判を見てみると、その店の店員の説明のわかりやすさをほめる書き込みがたくさんあった。値段だけでなく、こうした説明の丁寧さも、店を選ぶ大切な理由だと感じた。私もこの店でまた買い物をしようと思う。"},
    {"t": "reading", "s": "chuu", "q": "「集合日」の目的は何ですか。", "o": ["会議をたくさん行うこと。", "出社する社員の数を減らすこと。", "同僚と自然に話せる機会をつくること。", "通勤の時間をなくすこと。"], "a": 2, "x": "Hari kumpul tanpa rapat, diisi makan siang dan ngobrol, untuk menciptakan kesempatan bicara alami.", "p": "在宅勤務が広まって数年がたつ。通勤の時間がなくなり、自分のペースで仕事ができるという利点は、多くの人が認めている。一方で、「同僚との雑談が減って、アイデアが生まれにくくなった」という声も少なくない。ある会社では、この問題を解決するために、週に一日だけ全員が出社する「集合日」を設けた。その日は会議を入れず、昼食を一緒にとったり、ゆっくり話したりする時間にしている。始めた当初は、「出社が面倒だ」と不満を言う社員もいた。しかし、数か月たつと、「集合日に話したことが仕事のヒントになった」という意見が増え、今では多くの社員が集合日を楽しみにしているという。ある社員は、「画面の前では言えなかった小さな疑問も、昼食の時なら気軽に相談できる」と話している。会議のように目的が決まっていない時間だからこそ、肩の力を抜いて話せるのだろう。この会社の例からわかるのは、働き方の自由度を上げるだけでなく、人と人とが自然に話せる機会をどう作るかも、同じくらい大切だということだ。"},
    {"t": "reading", "s": "chuu", "q": "集合日を始めたあとの社員の様子として、正しいものはどれですか。", "o": ["最初から、全員が集合日に賛成した。", "最初は不満もあったが、だんだん集合日を楽しみにする人が増えた。", "不満が増えて、集合日をやめることになった。", "集合日には会議が増えて、社員が忙しくなった。"], "a": 1, "x": "Awalnya ada yang mengeluh, tetapi setelah beberapa bulan makin banyak yang menantikannya.", "p": "在宅勤務が広まって数年がたつ。通勤の時間がなくなり、自分のペースで仕事ができるという利点は、多くの人が認めている。一方で、「同僚との雑談が減って、アイデアが生まれにくくなった」という声も少なくない。ある会社では、この問題を解決するために、週に一日だけ全員が出社する「集合日」を設けた。その日は会議を入れず、昼食を一緒にとったり、ゆっくり話したりする時間にしている。始めた当初は、「出社が面倒だ」と不満を言う社員もいた。しかし、数か月たつと、「集合日に話したことが仕事のヒントになった」という意見が増え、今では多くの社員が集合日を楽しみにしているという。ある社員は、「画面の前では言えなかった小さな疑問も、昼食の時なら気軽に相談できる」と話している。会議のように目的が決まっていない時間だからこそ、肩の力を抜いて話せるのだろう。この会社の例からわかるのは、働き方の自由度を上げるだけでなく、人と人とが自然に話せる機会をどう作るかも、同じくらい大切だということだ。"},
    {"t": "reading", "s": "chuu", "q": "筆者が最も言いたいことは何ですか。", "o": ["在宅勤務は、会社にとって利点がない。", "全員が毎日出社するのが、一番よい働き方だ。", "自由な働き方に加えて、人が自然に話せる機会をつくることも大切だ。", "雑談は仕事の邪魔になるので、減らすべきだ。"], "a": 2, "x": "Kesimpulan penulis: selain fleksibilitas kerja, kesempatan bicara alami sama pentingnya.", "p": "在宅勤務が広まって数年がたつ。通勤の時間がなくなり、自分のペースで仕事ができるという利点は、多くの人が認めている。一方で、「同僚との雑談が減って、アイデアが生まれにくくなった」という声も少なくない。ある会社では、この問題を解決するために、週に一日だけ全員が出社する「集合日」を設けた。その日は会議を入れず、昼食を一緒にとったり、ゆっくり話したりする時間にしている。始めた当初は、「出社が面倒だ」と不満を言う社員もいた。しかし、数か月たつと、「集合日に話したことが仕事のヒントになった」という意見が増え、今では多くの社員が集合日を楽しみにしているという。ある社員は、「画面の前では言えなかった小さな疑問も、昼食の時なら気軽に相談できる」と話している。会議のように目的が決まっていない時間だからこそ、肩の力を抜いて話せるのだろう。この会社の例からわかるのは、働き方の自由度を上げるだけでなく、人と人とが自然に話せる機会をどう作るかも、同じくらい大切だということだ。"},
    {"t": "reading", "s": "chuu", "q": "子どものころ、「私」が梅干し作りの手伝いを嫌いだったのは、なぜですか。", "o": ["祖母に厳しくしかられたから。", "梅の実が重くて、運べなかったから。", "庭が暑くて、外に出たくなかったから。", "同じような作業が続いて、つまらなく思えたから。"], "a": 3, "x": "Pekerjaan mencuci dan mengelap buah satu per satu terasa monoton.", "p": "毎年六月になると、祖母は庭の梅の実を収穫して、梅干しを作る。子どものころの私は、その手伝いが嫌いだった。実を洗って、一つずつ布でふくだけの単調な作業に思えたからだ。それに、梅干し自体もすっぱくて、あまり好きではなかった。ところが、大学で一人暮らしを始めてから、状況が変わった。ある日、風邪をひいて寝込んでいた時に、祖母が送ってくれた梅干しでおかゆを食べたら、驚くほどおいしく感じたのだ。電話でそのことを伝えると、祖母は「梅干しは、食べる人の体を思いながら作るものだからね」と笑った。それからは、毎年六月が近づくと、あのすっぱい香りが無性に恋しくなるようになった。庭の梅の木も、子どものころより小さく見えるのが不思議だった。去年の夏、私は初めて自分から手伝いを申し出た。祖母は少し驚いた顔をしたが、すぐに「じゃあ、洗い方から教えよう」と言って、うれしそうに私を庭へ連れていってくれた。"},
    {"t": "reading", "s": "chuu", "q": "「私」が梅干しを見直したきっかけは何ですか。", "o": ["大学で梅干しの作り方を習ったこと。", "祖母が電話で、作り方を教えてくれたこと。", "自分で梅干しを作って、うまくいったこと。", "風邪をひいた時に、祖母の梅干しでおかゆを食べておいしく感じたこと。"], "a": 3, "x": "Saat flu di perantauan, bubur dengan umeboshi kiriman nenek terasa sangat enak.", "p": "毎年六月になると、祖母は庭の梅の実を収穫して、梅干しを作る。子どものころの私は、その手伝いが嫌いだった。実を洗って、一つずつ布でふくだけの単調な作業に思えたからだ。それに、梅干し自体もすっぱくて、あまり好きではなかった。ところが、大学で一人暮らしを始めてから、状況が変わった。ある日、風邪をひいて寝込んでいた時に、祖母が送ってくれた梅干しでおかゆを食べたら、驚くほどおいしく感じたのだ。電話でそのことを伝えると、祖母は「梅干しは、食べる人の体を思いながら作るものだからね」と笑った。それからは、毎年六月が近づくと、あのすっぱい香りが無性に恋しくなるようになった。庭の梅の木も、子どものころより小さく見えるのが不思議だった。去年の夏、私は初めて自分から手伝いを申し出た。祖母は少し驚いた顔をしたが、すぐに「じゃあ、洗い方から教えよう」と言って、うれしそうに私を庭へ連れていってくれた。"},
    {"t": "reading", "s": "chuu", "q": "去年の夏の祖母の気持ちとして、合うものはどれですか。", "o": ["「私」の手伝いが心配で、断りたいと思った。", "「私」が手伝うと言ったことに驚いたが、うれしく思った。", "「私」が遅れて来たことに、腹を立てた。", "作り方を教えるのを、面倒に思った。"], "a": 1, "x": "Nenek 'sedikit terkejut' lalu 'senang' mengajak ke kebun.", "p": "毎年六月になると、祖母は庭の梅の実を収穫して、梅干しを作る。子どものころの私は、その手伝いが嫌いだった。実を洗って、一つずつ布でふくだけの単調な作業に思えたからだ。それに、梅干し自体もすっぱくて、あまり好きではなかった。ところが、大学で一人暮らしを始めてから、状況が変わった。ある日、風邪をひいて寝込んでいた時に、祖母が送ってくれた梅干しでおかゆを食べたら、驚くほどおいしく感じたのだ。電話でそのことを伝えると、祖母は「梅干しは、食べる人の体を思いながら作るものだからね」と笑った。それからは、毎年六月が近づくと、あのすっぱい香りが無性に恋しくなるようになった。庭の梅の木も、子どものころより小さく見えるのが不思議だった。去年の夏、私は初めて自分から手伝いを申し出た。祖母は少し驚いた顔をしたが、すぐに「じゃあ、洗い方から教えよう」と言って、うれしそうに私を庭へ連れていってくれた。"},
    {"t": "reading", "s": "chuu", "q": "レジ袋の有料化について、この文章に書かれていることはどれですか。", "o": ["使用量はほとんど変わらなかった。", "始めた当初から、多くの人が賛成していた。", "使用量は大きく減ったが、それだけで問題が解決したとは言えない。", "エコバッグを買う必要はないことがわかった。"], "a": 2, "x": "Penggunaan kantong plastik turun, tetapi tas ramah lingkungan yang menumpuk di rumah tetap jadi masalah.", "p": "スーパーでレジ袋が有料になって、しばらくたつ。当初は「たった数円のことで環境が良くなるのか」と疑う声も多かったが、実際には、ほとんどの客が自分の袋を持ってくるようになり、レジ袋の使用量は大きく減ったそうだ。とはいえ、これで問題がすべて解決したわけではない。ある調査によると、買い物袋の代わりに買った丈夫なエコバッグを、自宅にいくつも持っている人が少なくない。エコバッグも作るときには資源を使うので、何度も使わなければ、かえって環境に負担をかけることになる。店によっては、おしゃれなバッグを次々に売り出しているところもある。流行に合わせて買い替えるうちに、使わなくなったバッグが増えていくのは、本末転倒ではないだろうか。大切なのは、新しいものを買うことではなく、今あるものを長く使い続けることではないだろうか。"},
    {"t": "reading", "s": "chuu", "q": "筆者が最も言いたいことは何ですか。", "o": ["新しい物を買うより、持っている物を長く使い続けることが大切だ。", "エコバッグは、たくさん買うほど環境によい。", "レジ袋は、再び無料に戻すべきだ。", "エコバッグは、作る時に資源を使わないので問題がない。"], "a": 0, "x": "Penulis menutup dengan: yang penting bukan membeli baru, melainkan memakai lama yang sudah ada.", "p": "スーパーでレジ袋が有料になって、しばらくたつ。当初は「たった数円のことで環境が良くなるのか」と疑う声も多かったが、実際には、ほとんどの客が自分の袋を持ってくるようになり、レジ袋の使用量は大きく減ったそうだ。とはいえ、これで問題がすべて解決したわけではない。ある調査によると、買い物袋の代わりに買った丈夫なエコバッグを、自宅にいくつも持っている人が少なくない。エコバッグも作るときには資源を使うので、何度も使わなければ、かえって環境に負担をかけることになる。店によっては、おしゃれなバッグを次々に売り出しているところもある。流行に合わせて買い替えるうちに、使わなくなったバッグが増えていくのは、本末転倒ではないだろうか。大切なのは、新しいものを買うことではなく、今あるものを長く使い続けることではないだろうか。"},
    {"t": "reading", "s": "chuu", "q": "以前の「私」は、どうでしたか。", "o": ["間違えても気にせず、誰とでも話していた。", "間違えるのが恥ずかしくて、話す機会を避けていた。", "留学の機会を、自分から探していた。", "基礎の勉強を、まったくしなかった。"], "a": 1, "x": "Dulu penulis malu salah dan menghindari kesempatan memakai ungkapan yang dipelajari.", "p": "外国語を勉強していると、「完璧に話せるようになってから外国人と話そう」と考えてしまう人が多い。私も以前はそうだった。間違えるのが恥ずかしくて、勉強した表現を使う機会を自分から避けていたのだ。しかし、留学中に出会った友人に言われた一言で、考えが変わった。「間違いは、会話の邪魔じゃない。会話を続けるための材料だよ」。確かに、私が間違えると、相手は言い直して教えてくれたし、そこから話が広がることも多かった。留学先の街では、店の人も近所の人も、私の下手な言葉を笑わずに、最後まで聞いてくれた。通じない時は、身振りや絵を使って、何とか伝えようとした。そのやり取り自体が、何よりの勉強になったのである。それ以来、私は完璧さより、話そうとする気持ちを大切にしている。もちろん、基礎をしっかり学ぶことは大事だが、それだけでは言葉は使えるようにならない。使ってみて初めて、本当に身につくのだと思う。"},
    {"t": "reading", "s": "chuu", "q": "外国語の勉強について、筆者の考えに合うものはどれですか。", "o": ["基礎より、会話の練習だけをするべきだ。", "基礎は大切だが、実際に使ってみて初めて身につく。", "完璧に話せるまで、人とは話さないほうがよい。", "友人は、相手の間違いを直さないほうがよい。"], "a": 1, "x": "Basis penting, tetapi baru benar-benar dikuasai setelah dipakai.", "p": "外国語を勉強していると、「完璧に話せるようになってから外国人と話そう」と考えてしまう人が多い。私も以前はそうだった。間違えるのが恥ずかしくて、勉強した表現を使う機会を自分から避けていたのだ。しかし、留学中に出会った友人に言われた一言で、考えが変わった。「間違いは、会話の邪魔じゃない。会話を続けるための材料だよ」。確かに、私が間違えると、相手は言い直して教えてくれたし、そこから話が広がることも多かった。留学先の街では、店の人も近所の人も、私の下手な言葉を笑わずに、最後まで聞いてくれた。通じない時は、身振りや絵を使って、何とか伝えようとした。そのやり取り自体が、何よりの勉強になったのである。それ以来、私は完璧さより、話そうとする気持ちを大切にしている。もちろん、基礎をしっかり学ぶことは大事だが、それだけでは言葉は使えるようにならない。使ってみて初めて、本当に身につくのだと思う。"},
    {"t": "reading", "s": "chuu", "q": "この書店が客を増やしている工夫は何ですか。", "o": ["ネットより安い値段で本を売っていること。", "注文された本を、翌日に家へ届けていること。", "人気のある本だけを、たくさん置いていること。", "店主が選んだ本を、手書きの感想をつけて並べていること。"], "a": 3, "x": "Pemilik memilih buku sendiri dan memajangnya dengan kesan tulisan tangan.", "p": "町の小さな書店が減り続けている。インターネットで本が買えるようになり、わざわざ店まで足を運ばなくても、欲しい本が翌日には家に届くからだ。しかし、そんな中で、私の住む町の書店は、少し変わった工夫で客を増やしている。店主が一冊ずつ読んで選んだ本を、手書きの感想とともに並べているのだ。「この本を読んだ人が、次にどんな本を読むとよいか」まで書いてあるので、客は知らなかった本と出会うことができる。また、店の奥には小さな机があり、買った本をその場で読みながらお茶を飲むこともできる。常連の客が増え、客同士が本の感想を話し合う姿も見られるようになった。店主は「ネットは欲しい本を探すには便利だが、何を読めばいいかわからない人には、人が選んだ本のほうが役に立つ」と話す。便利さだけでは満たされない部分に、店が生き残るヒントがあるのかもしれない。"},
    {"t": "reading", "s": "chuu", "q": "店主の考えに合うものはどれですか。", "o": ["何を読めばよいかわからない人には、人が選んだ本が役に立つ。", "ネットで買えるので、書店はもう必要ない。", "欲しい本を探すには、ネットより書店のほうが便利だ。", "書店も、もっと便利なサービスを始めるべきだ。"], "a": 0, "x": "Internet praktis untuk mencari buku yang diinginkan, tetapi bagi yang bingung, buku pilihan orang lebih berguna.", "p": "町の小さな書店が減り続けている。インターネットで本が買えるようになり、わざわざ店まで足を運ばなくても、欲しい本が翌日には家に届くからだ。しかし、そんな中で、私の住む町の書店は、少し変わった工夫で客を増やしている。店主が一冊ずつ読んで選んだ本を、手書きの感想とともに並べているのだ。「この本を読んだ人が、次にどんな本を読むとよいか」まで書いてあるので、客は知らなかった本と出会うことができる。また、店の奥には小さな机があり、買った本をその場で読みながらお茶を飲むこともできる。常連の客が増え、客同士が本の感想を話し合う姿も見られるようになった。店主は「ネットは欲しい本を探すには便利だが、何を読めばいいかわからない人には、人が選んだ本のほうが役に立つ」と話す。便利さだけでは満たされない部分に、店が生き残るヒントがあるのかもしれない。"},
    {"t": "reading", "s": "tougou", "q": "小学生のスマートフォンについて、AとBはどう考えていますか。", "o": ["AもBも、小学生には持たせないほうがよいと考えている。", "Aは勉強のために必要だと考え、Bは遊びのために不要だと考えている。", "Aは持たせるのは早いと考え、Bは持たせたうえでルールを教えるべきだと考えている。", "AもBも、ルールがなくても自由に使わせてよいと考えている。"], "a": 2, "x": "A: masih terlalu dini. B: berikan dengan aturan dan ajarkan cara pakai.", "p": "【A】小学生にスマートフォンを持たせるのは、まだ早いと思う。画面を見る時間が長くなれば、外で遊んだり、家族と話したりする時間が減ってしまうからだ。連絡のためだけなら、通話と位置情報の機能だけを持つ携帯電話で十分である。使い方を自分で判断できる年齢になるまで、待つべきだ。\n【B】スマートフォンは、今や勉強にも欠かせない道具だ。調べ物や辞書、学習アプリなど、使い方次第で学びを助けてくれる。大切なのは持たせないことではなく、家庭でルールを決め、使い方を教えることだ。小学生のうちから正しい使い方を身につけさせたほうがよいと思う。"},
    {"t": "reading", "s": "tougou", "q": "Bだけが述べていることはどれですか。", "o": ["画面を見る時間が長くなる問題。", "通話機能だけの携帯電話で十分だということ。", "学習に役立つ使い方があること。", "外で遊ぶ時間が減ってしまうこと。"], "a": 2, "x": "Hanya B yang menyebut manfaat belajar (kamus, aplikasi belajar). Tiga lainnya adalah argumen A.", "p": "【A】小学生にスマートフォンを持たせるのは、まだ早いと思う。画面を見る時間が長くなれば、外で遊んだり、家族と話したりする時間が減ってしまうからだ。連絡のためだけなら、通話と位置情報の機能だけを持つ携帯電話で十分である。使い方を自分で判断できる年齢になるまで、待つべきだ。\n【B】スマートフォンは、今や勉強にも欠かせない道具だ。調べ物や辞書、学習アプリなど、使い方次第で学びを助けてくれる。大切なのは持たせないことではなく、家庭でルールを決め、使い方を教えることだ。小学生のうちから正しい使い方を身につけさせたほうがよいと思う。"},
    {"t": "reading", "s": "tougou", "q": "AとBの主な違いは何ですか。", "o": ["Aは値段を重視し、Bは内容の多さを重視している。", "Aは紙の本を勧め、Bは電子書籍を勧めている。", "AもBも、読みやすさだけを重視している。", "Aは便利さを重視し、Bは読むときの感覚を重視している。"], "a": 3, "x": "A menekankan kepraktisan e-book, B menekankan sensasi membaca buku kertas.", "p": "【A】電子書籍は、本棚の場所を取らず、旅行や出張にも何冊でも持っていけるのが魅力だ。文字の大きさも変えられるので、目の弱い人にも読みやすい。私は最近、新しく買う本のほとんどを電子書籍にしている。\n【B】私は、やはり紙の本のほうが好きだ。ページをめくる感覚や、本の重さ、インクのにおいなどが、読書の楽しみの一部になっているからだ。それに、紙の本は、どこまで読んだかが手や目で感覚的にわかるので、内容も覚えやすい気がする。"},
    {"t": "reading", "s": "tougou", "q": "Aが電子書籍の利点として挙げていないものはどれですか。", "o": ["場所を取らないこと。", "文字の大きさを変えられること。", "紙の本より値段が安いこと。", "何冊でも持ち歩けること。"], "a": 2, "x": "Harga murah tidak disebut dalam A.", "p": "【A】電子書籍は、本棚の場所を取らず、旅行や出張にも何冊でも持っていけるのが魅力だ。文字の大きさも変えられるので、目の弱い人にも読みやすい。私は最近、新しく買う本のほとんどを電子書籍にしている。\n【B】私は、やはり紙の本のほうが好きだ。ページをめくる感覚や、本の重さ、インクのにおいなどが、読書の楽しみの一部になっているからだ。それに、紙の本は、どこまで読んだかが手や目で感覚的にわかるので、内容も覚えやすい気がする。"},
    {"t": "reading", "s": "tougou", "q": "都会の暮らしについて、AとBはどう述べていますか。", "o": ["AもBも、家賃の高さが最大の問題だと述べている。", "Aは不便さを述べ、Bは経済的な利点だけを述べている。", "Aは利点を中心に述べ、Bは便利さの面でうらやましい点もあると述べている。", "AもBも、都会に住む必要はないと述べている。"], "a": 2, "x": "A memuji kota; B senang di daerah tetapi iri pada kemudahan kota, terutama rumah sakit.", "p": "【A】都会は、仕事の選択肢が多く、病院や店も近くにそろっている。確かに家賃は高いが、移動の時間が短く、その分を自分の時間に使える。若いうちにいろいろな人と出会い、経験を積むには、都会で暮らすのが一番だと思う。\n【B】私は三年前に、都会から地方の町に引っ越した。家賃が安く、庭付きの広い家に住めるようになった。リモートで仕事ができるので、仕事の面で困ることもない。ただ、近くに大きな病院がないのは不安なので、その点は都会の便利さが少しうらやましい。"},
    {"t": "reading", "s": "tougou", "q": "Bの筆者について、合うものはどれですか。", "o": ["仕事が見つからず、都会へ戻りたいと思っている。", "家賃が高くなったことを、後悔している。", "仕事は地方でも問題ないが、医療の面で不安がある。", "医療も買い物も、地方のほうが便利だと感じている。"], "a": 2, "x": "B bisa bekerja jarak jauh, tetapi khawatir karena tidak ada rumah sakit besar dekat.", "p": "【A】都会は、仕事の選択肢が多く、病院や店も近くにそろっている。確かに家賃は高いが、移動の時間が短く、その分を自分の時間に使える。若いうちにいろいろな人と出会い、経験を積むには、都会で暮らすのが一番だと思う。\n【B】私は三年前に、都会から地方の町に引っ越した。家賃が安く、庭付きの広い家に住めるようになった。リモートで仕事ができるので、仕事の面で困ることもない。ただ、近くに大きな病院がないのは不安なので、その点は都会の便利さが少しうらやましい。"},
    {"t": "reading", "s": "shuchou", "q": "筆者が、手書きは考えを整理する助けになると考える理由は何ですか。", "o": ["書く速度が遅いので、書く前に内容を考えることになるから。", "手書きのほうが、キーボードより速く書けるから。", "手で書くと、漢字を忘れずに済むから。", "会議のメモを書かなくてよくなるから。"], "a": 0, "x": "Menulis tangan lambat, sehingga orang terpaksa memikirkan isinya dulu.", "p": "パソコンやスマートフォンが普及して、手で文字を書く機会は大きく減った。漢字は、読めても書けないという人が増えているとよく言われる。そのため、「手書きはもう時代遅れだ」と考える人もいるかもしれない。しかし、私は、手書きにはこれからも守るべき価値があると考えている。\n\n第一に、手で書くという行為は、考えを整理する助けになる。キーボードなら、頭に浮かんだ言葉をそのまま速く入力できるが、手書きは、書く速度が遅いぶん、書く前に何を書くかを考えざるをえない。この「遅さ」が、かえって内容を深く考えることにつながるのだ。実際、会議のメモや日記を手で書いている人は、あとで読み返した時に内容をよく思い出せると話すことが多い。\n\n第二に、手書きの文字には、書いた人の気持ちが伝わりやすい。たとえば、誕生日のカードやお礼の手紙は、同じ言葉でも、印刷された文字より、少し不ぞろいな手書きの文字のほうが、温かく感じられる。相手のために時間をかけたことが、文字の形から伝わるからだろう。\n\n第三に、手で書くことは、漢字を覚えることにもつながる。何度も書くうちに、手が文字の形を覚えるからだ。入力して変換するだけでは、読めても書けない漢字が増えていってしまう。\n\nもちろん、すべてを手書きに戻すべきだと言うつもりはない。仕事の文書や長い文章は、パソコンを使ったほうが効率的である。大切なのは、目的に合わせて道具を選ぶことだ。考えを深めたい時や気持ちを伝えたい時には、手書きという選択肢を残しておきたい。手書きを「できる人」が減ってしまえば、その選択肢そのものがなくなってしまうからである。"},
    {"t": "reading", "s": "shuchou", "q": "筆者の意見として、合うものはどれですか。", "o": ["仕事の文書も、すべて手書きにするべきだ。", "手書きは時代遅れなので、やめてよい。", "目的に合わせて使い分け、手書きという選択肢も残すべきだ。", "パソコンは、考えを深めるのにまったく向いていない。"], "a": 2, "x": "Penulis tidak menolak PC untuk dokumen kerja; ia ingin pilihan tulisan tangan dipertahankan.", "p": "パソコンやスマートフォンが普及して、手で文字を書く機会は大きく減った。漢字は、読めても書けないという人が増えているとよく言われる。そのため、「手書きはもう時代遅れだ」と考える人もいるかもしれない。しかし、私は、手書きにはこれからも守るべき価値があると考えている。\n\n第一に、手で書くという行為は、考えを整理する助けになる。キーボードなら、頭に浮かんだ言葉をそのまま速く入力できるが、手書きは、書く速度が遅いぶん、書く前に何を書くかを考えざるをえない。この「遅さ」が、かえって内容を深く考えることにつながるのだ。実際、会議のメモや日記を手で書いている人は、あとで読み返した時に内容をよく思い出せると話すことが多い。\n\n第二に、手書きの文字には、書いた人の気持ちが伝わりやすい。たとえば、誕生日のカードやお礼の手紙は、同じ言葉でも、印刷された文字より、少し不ぞろいな手書きの文字のほうが、温かく感じられる。相手のために時間をかけたことが、文字の形から伝わるからだろう。\n\n第三に、手で書くことは、漢字を覚えることにもつながる。何度も書くうちに、手が文字の形を覚えるからだ。入力して変換するだけでは、読めても書けない漢字が増えていってしまう。\n\nもちろん、すべてを手書きに戻すべきだと言うつもりはない。仕事の文書や長い文章は、パソコンを使ったほうが効率的である。大切なのは、目的に合わせて道具を選ぶことだ。考えを深めたい時や気持ちを伝えたい時には、手書きという選択肢を残しておきたい。手書きを「できる人」が減ってしまえば、その選択肢そのものがなくなってしまうからである。"},
    {"t": "reading", "s": "shuchou", "q": "筆者は、手書きの手紙が温かく感じられるのはなぜだと考えていますか。", "o": ["印刷された文字より、読みやすいから。", "相手のために時間をかけたことが、文字の形から伝わるから。", "文字が不ぞろいなので、上手に見えるから。", "同じ言葉でも、手書きのほうが意味が深いから。"], "a": 1, "x": "Waktu yang dicurahkan untuk lawan bicara terasa dari bentuk huruf.", "p": "パソコンやスマートフォンが普及して、手で文字を書く機会は大きく減った。漢字は、読めても書けないという人が増えているとよく言われる。そのため、「手書きはもう時代遅れだ」と考える人もいるかもしれない。しかし、私は、手書きにはこれからも守るべき価値があると考えている。\n\n第一に、手で書くという行為は、考えを整理する助けになる。キーボードなら、頭に浮かんだ言葉をそのまま速く入力できるが、手書きは、書く速度が遅いぶん、書く前に何を書くかを考えざるをえない。この「遅さ」が、かえって内容を深く考えることにつながるのだ。実際、会議のメモや日記を手で書いている人は、あとで読み返した時に内容をよく思い出せると話すことが多い。\n\n第二に、手書きの文字には、書いた人の気持ちが伝わりやすい。たとえば、誕生日のカードやお礼の手紙は、同じ言葉でも、印刷された文字より、少し不ぞろいな手書きの文字のほうが、温かく感じられる。相手のために時間をかけたことが、文字の形から伝わるからだろう。\n\n第三に、手で書くことは、漢字を覚えることにもつながる。何度も書くうちに、手が文字の形を覚えるからだ。入力して変換するだけでは、読めても書けない漢字が増えていってしまう。\n\nもちろん、すべてを手書きに戻すべきだと言うつもりはない。仕事の文書や長い文章は、パソコンを使ったほうが効率的である。大切なのは、目的に合わせて道具を選ぶことだ。考えを深めたい時や気持ちを伝えたい時には、手書きという選択肢を残しておきたい。手書きを「できる人」が減ってしまえば、その選択肢そのものがなくなってしまうからである。"},
    {"t": "reading", "s": "shuchou", "q": "筆者は、親が先回りして手助けすることをどう考えていますか。", "o": ["愛情からの行動だが、子どもが学ぶ機会を奪うのでよくない。", "愛情がないからする行動なので、すぐにやめるべきだ。", "子どもを守るために、もっと増やすべきだ。", "子どもがけんかを覚えるので、役に立つ行動だ。"], "a": 0, "x": "Penulis mengakui itu berasal dari kasih sayang, tetapi menilai merampas kesempatan belajar dari kegagalan kecil.", "p": "最近、子どもが失敗しないように、親が先回りして手助けをするケースが増えているという。忘れ物がないように前の晩に持ち物を確認してやる、友達とけんかをしそうになると間に入る、宿題が終わっていなければ代わりに手伝う。親としては、子どもに嫌な思いをさせたくないという愛情からの行動なのだろう。しかし、私は、子どもが小さな失敗を経験する機会を大人が奪ってしまうのは、よくないと考える。\n\n失敗は、決して無駄な経験ではない。たとえば、忘れ物をして困った子どもは、次からは自分で確認しようと思うようになる。友達とけんかをした子どもは、どう言えば相手が傷つくかを、痛みを伴って学ぶ。こうした経験を通して、子どもは自分で考え、行動を変える力を身につけていく。親が先回りをしてしまえば、その学びの機会は失われる。\n\nさらに問題なのは、失敗を経験していない子どもは、大人になって大きな失敗をした時に、立ち直るのが難しくなるということだ。小さな失敗なら、すぐにやり直せる。その経験を積んでいれば、「失敗しても何とかなる」という自信が生まれる。この自信こそが、将来の困難に立ち向かう力になるのではないか。\n\n実際、ある学校の先生は、「困った経験のない子ほど、思いどおりにならない時にすぐあきらめてしまう」と話している。失敗した時にどうすれば立て直せるかを、子どもが自分で考える場面を、大人はもっと大切にすべきだろう。\n\nもちろん、命に関わる危険や、取り返しのつかない失敗まで、子どもに任せろと言うのではない。そうした場合は、親が守る必要がある。だが、そうでない失敗に対しては、手を出したい気持ちをぐっとこらえ、見守る勇気を持つことが、親には求められていると思う。"},
    {"t": "reading", "s": "shuchou", "q": "失敗を経験していない子どもが大人になると、どうなると筆者は述べていますか。", "o": ["大きな失敗をした時に、立ち直るのが難しくなる。", "小さな失敗を、何度も繰り返すようになる。", "他の人の失敗に対して、厳しくなる。", "親に頼らず、何でも自分で決めるようになる。"], "a": 0, "x": "Tanpa pengalaman gagal kecil, sulit bangkit saat gagal besar.", "p": "最近、子どもが失敗しないように、親が先回りして手助けをするケースが増えているという。忘れ物がないように前の晩に持ち物を確認してやる、友達とけんかをしそうになると間に入る、宿題が終わっていなければ代わりに手伝う。親としては、子どもに嫌な思いをさせたくないという愛情からの行動なのだろう。しかし、私は、子どもが小さな失敗を経験する機会を大人が奪ってしまうのは、よくないと考える。\n\n失敗は、決して無駄な経験ではない。たとえば、忘れ物をして困った子どもは、次からは自分で確認しようと思うようになる。友達とけんかをした子どもは、どう言えば相手が傷つくかを、痛みを伴って学ぶ。こうした経験を通して、子どもは自分で考え、行動を変える力を身につけていく。親が先回りをしてしまえば、その学びの機会は失われる。\n\nさらに問題なのは、失敗を経験していない子どもは、大人になって大きな失敗をした時に、立ち直るのが難しくなるということだ。小さな失敗なら、すぐにやり直せる。その経験を積んでいれば、「失敗しても何とかなる」という自信が生まれる。この自信こそが、将来の困難に立ち向かう力になるのではないか。\n\n実際、ある学校の先生は、「困った経験のない子ほど、思いどおりにならない時にすぐあきらめてしまう」と話している。失敗した時にどうすれば立て直せるかを、子どもが自分で考える場面を、大人はもっと大切にすべきだろう。\n\nもちろん、命に関わる危険や、取り返しのつかない失敗まで、子どもに任せろと言うのではない。そうした場合は、親が守る必要がある。だが、そうでない失敗に対しては、手を出したい気持ちをぐっとこらえ、見守る勇気を持つことが、親には求められていると思う。"},
    {"t": "reading", "s": "shuchou", "q": "親に求められることとして、筆者が述べているのはどれですか。", "o": ["失敗しないように、すべてのことを手伝うこと。", "子どもがけんかをしないよう、いつも間に入ること。", "取り返しのつかない場合を除き、手を出さずに見守ること。", "命に関わる場合も、子どもに任せること。"], "a": 2, "x": "Kecuali bahaya serius, orang tua diminta menahan diri dan mengawasi.", "p": "最近、子どもが失敗しないように、親が先回りして手助けをするケースが増えているという。忘れ物がないように前の晩に持ち物を確認してやる、友達とけんかをしそうになると間に入る、宿題が終わっていなければ代わりに手伝う。親としては、子どもに嫌な思いをさせたくないという愛情からの行動なのだろう。しかし、私は、子どもが小さな失敗を経験する機会を大人が奪ってしまうのは、よくないと考える。\n\n失敗は、決して無駄な経験ではない。たとえば、忘れ物をして困った子どもは、次からは自分で確認しようと思うようになる。友達とけんかをした子どもは、どう言えば相手が傷つくかを、痛みを伴って学ぶ。こうした経験を通して、子どもは自分で考え、行動を変える力を身につけていく。親が先回りをしてしまえば、その学びの機会は失われる。\n\nさらに問題なのは、失敗を経験していない子どもは、大人になって大きな失敗をした時に、立ち直るのが難しくなるということだ。小さな失敗なら、すぐにやり直せる。その経験を積んでいれば、「失敗しても何とかなる」という自信が生まれる。この自信こそが、将来の困難に立ち向かう力になるのではないか。\n\n実際、ある学校の先生は、「困った経験のない子ほど、思いどおりにならない時にすぐあきらめてしまう」と話している。失敗した時にどうすれば立て直せるかを、子どもが自分で考える場面を、大人はもっと大切にすべきだろう。\n\nもちろん、命に関わる危険や、取り返しのつかない失敗まで、子どもに任せろと言うのではない。そうした場合は、親が守る必要がある。だが、そうでない失敗に対しては、手を出したい気持ちをぐっとこらえ、見守る勇気を持つことが、親には求められていると思う。"},
    {"t": "reading", "s": "shuchou", "q": "筆者は、観光客の数を制限する方法をどう評価していますか。", "o": ["長い目で見ても、最もよい方法である。", "まったく効果がなく、意味がない。", "短期的には効果があるが、根本的な解決にはならない。", "地元の人の収入が増えるので、よい方法である。"], "a": 2, "x": "Efektif jangka pendek, tetapi pendapatan warga turun sehingga bukan solusi mendasar.", "p": "有名な観光地では、観光客が増えすぎて、地元の人々の生活に影響が出る「オーバーツーリズム」が問題になっている。道路が渋滞して、バスに乗れない。静かな住宅地に観光客が入り込み、ごみを捨てたり大声で話したりする。こうした状況では、地元の人が観光客に対して否定的な気持ちを持つのも無理はない。\n\nこの問題への対策として、観光客の数を制限する、入場料を高くするといった方法が考えられている。確かに、数を減らすことは、短期的には効果があるだろう。しかし、私は、それだけでは根本的な解決にならないと思う。なぜなら、観光客が来なくなれば、観光で生計を立てている地元の人々の収入も減ってしまうからだ。観光は、多くの地域にとって大切な産業であり、問題は「観光客がいること」ではなく、「観光客が一か所に集中しすぎること」にあるのだ。\n\nそこで、私は、観光客を分散させる工夫が必要だと考える。たとえば、有名な場所だけでなく、あまり知られていない近くの町や自然を紹介することで、訪れる場所や時間をずらしてもらう。また、地元の文化や暮らしのルールを、来る前にわかりやすく伝えておくことも重要だ。ルールを知らないために起こるトラブルは、事前の情報提供でかなり防げるはずである。\n\nさらに、観光で得た収入の一部を、地域の道路やごみ処理の整備に使う仕組みも考えられる。観光客が増えることで生まれる負担を、観光の利益で支えることができれば、地元の人も観光客を受け入れやすくなるはずだ。\n\n観光客と地元の人が、お互いを尊重しながら過ごせる地域をつくること。それが、これからの観光に求められていることではないだろうか。"},
    {"t": "reading", "s": "shuchou", "q": "筆者によると、問題の本質は何ですか。", "o": ["観光客が、地元の文化に興味を持たないこと。", "観光で生計を立てる人が増えすぎたこと。", "観光客が一か所に集中しすぎていること。", "入場料が安すぎること。"], "a": 2, "x": "Masalahnya bukan adanya turis, melainkan turis terkonsentrasi di satu tempat.", "p": "有名な観光地では、観光客が増えすぎて、地元の人々の生活に影響が出る「オーバーツーリズム」が問題になっている。道路が渋滞して、バスに乗れない。静かな住宅地に観光客が入り込み、ごみを捨てたり大声で話したりする。こうした状況では、地元の人が観光客に対して否定的な気持ちを持つのも無理はない。\n\nこの問題への対策として、観光客の数を制限する、入場料を高くするといった方法が考えられている。確かに、数を減らすことは、短期的には効果があるだろう。しかし、私は、それだけでは根本的な解決にならないと思う。なぜなら、観光客が来なくなれば、観光で生計を立てている地元の人々の収入も減ってしまうからだ。観光は、多くの地域にとって大切な産業であり、問題は「観光客がいること」ではなく、「観光客が一か所に集中しすぎること」にあるのだ。\n\nそこで、私は、観光客を分散させる工夫が必要だと考える。たとえば、有名な場所だけでなく、あまり知られていない近くの町や自然を紹介することで、訪れる場所や時間をずらしてもらう。また、地元の文化や暮らしのルールを、来る前にわかりやすく伝えておくことも重要だ。ルールを知らないために起こるトラブルは、事前の情報提供でかなり防げるはずである。\n\nさらに、観光で得た収入の一部を、地域の道路やごみ処理の整備に使う仕組みも考えられる。観光客が増えることで生まれる負担を、観光の利益で支えることができれば、地元の人も観光客を受け入れやすくなるはずだ。\n\n観光客と地元の人が、お互いを尊重しながら過ごせる地域をつくること。それが、これからの観光に求められていることではないだろうか。"},
    {"t": "reading", "s": "shuchou", "q": "筆者が提案している対策として、合うものはどれですか。", "o": ["あまり知られていない場所を紹介し、来る前にルールを伝える。", "有名な場所の入場料を、大幅に上げる。", "観光客が住宅地に入れないように、道を閉鎖する。", "地元の人に、観光客への説明をお願いする。"], "a": 0, "x": "Usulan: promosikan tempat kurang dikenal untuk menyebar turis dan beri tahu aturan sebelum datang.", "p": "有名な観光地では、観光客が増えすぎて、地元の人々の生活に影響が出る「オーバーツーリズム」が問題になっている。道路が渋滞して、バスに乗れない。静かな住宅地に観光客が入り込み、ごみを捨てたり大声で話したりする。こうした状況では、地元の人が観光客に対して否定的な気持ちを持つのも無理はない。\n\nこの問題への対策として、観光客の数を制限する、入場料を高くするといった方法が考えられている。確かに、数を減らすことは、短期的には効果があるだろう。しかし、私は、それだけでは根本的な解決にならないと思う。なぜなら、観光客が来なくなれば、観光で生計を立てている地元の人々の収入も減ってしまうからだ。観光は、多くの地域にとって大切な産業であり、問題は「観光客がいること」ではなく、「観光客が一か所に集中しすぎること」にあるのだ。\n\nそこで、私は、観光客を分散させる工夫が必要だと考える。たとえば、有名な場所だけでなく、あまり知られていない近くの町や自然を紹介することで、訪れる場所や時間をずらしてもらう。また、地元の文化や暮らしのルールを、来る前にわかりやすく伝えておくことも重要だ。ルールを知らないために起こるトラブルは、事前の情報提供でかなり防げるはずである。\n\nさらに、観光で得た収入の一部を、地域の道路やごみ処理の整備に使う仕組みも考えられる。観光客が増えることで生まれる負担を、観光の利益で支えることができれば、地元の人も観光客を受け入れやすくなるはずだ。\n\n観光客と地元の人が、お互いを尊重しながら過ごせる地域をつくること。それが、これからの観光に求められていることではないだろうか。"},
    {"t": "reading", "s": "jouhou", "q": "市内に住む佐藤さんは、平日の午後六時以降に参加でき、割引後の受講料が5,000円以下の講座を受けたいと思っています。どの講座がよいですか。", "o": ["写真の撮り方入門", "手作りパン教室", "やさしい英会話", "太極拳"], "a": 3, "x": "Hanya D yang malam hari (18:30) dan setelah diskon 10% menjadi 4.320 yen. B menjadi 5.040 yen (lebih dari 5.000). C dan E tidak malam hari.", "p": "【市民カルチャー講座　後期受講生募集】\n講座名／曜日・時間／定員／受講料（全8回）\nA　初めての水彩画／火曜　10:00〜12:00／15名／6,400円（絵の具代は別）\nB　写真の撮り方入門／水曜　19:00〜21:00／20名／5,600円\nC　やさしい英会話／木曜　10:30〜12:00／12名／7,200円（教材費込み）\nD　太極拳／金曜　18:30〜20:00／25名／4,800円\nE　手作りパン教室／土曜　13:00〜15:30／10名／8,800円（材料費込み）\n※市内在住の方は受講料が10%割引。市外の方は割引なし。\n※申し込みは先着順。定員になり次第、締め切ります。\n※欠席した場合の振り替えはできません。"},
    {"t": "reading", "s": "jouhou", "q": "市外に住む田中さんが「やさしい英会話」を受けるとき、受講料はいくらですか。", "o": ["6,480円", "7,920円", "7,200円", "8,000円"], "a": 2, "x": "Warga luar kota tidak mendapat diskon, jadi tetap 7.200 yen (bahan ajar sudah termasuk).", "p": "【市民カルチャー講座　後期受講生募集】\n講座名／曜日・時間／定員／受講料（全8回）\nA　初めての水彩画／火曜　10:00〜12:00／15名／6,400円（絵の具代は別）\nB　写真の撮り方入門／水曜　19:00〜21:00／20名／5,600円\nC　やさしい英会話／木曜　10:30〜12:00／12名／7,200円（教材費込み）\nD　太極拳／金曜　18:30〜20:00／25名／4,800円\nE　手作りパン教室／土曜　13:00〜15:30／10名／8,800円（材料費込み）\n※市内在住の方は受講料が10%割引。市外の方は割引なし。\n※申し込みは先着順。定員になり次第、締め切ります。\n※欠席した場合の振り替えはできません。"},
    {"t": "reading", "s": "jouhou", "q": "次の人のうち、応募できるのはだれですか。", "o": ["調理の経験はないが、キッチンで働きたい大学生。", "月曜日から金曜日まで、週に五日働ける大学生。", "土曜日に働ける高校生。", "調理の経験はなく、ホールで働きたい。土曜日と平日の二日、週に三日働ける大学生。"], "a": 3, "x": "Syarat: bukan SMA, minimal 2 hari/minggu dengan salah satu akhir pekan, dapur wajib berpengalaman. Hanya pilihan pertama yang memenuhi.", "p": "【カフェ「ひだまり」スタッフ募集】\n・仕事内容：ホール（接客）／キッチン（調理補助）\n・時給：ホール　1,100円／キッチン　1,200円　※22時以降は25%増し\n・勤務時間：①8:00〜14:00　②12:00〜18:00　③17:00〜23:00（いずれも休憩あり）\n・勤務日：週2日以上（土日のどちらか1日は必ず入れる方）\n・応募条件：高校生は不可。キッチンは、調理の経験がある方のみ。\n・待遇：交通費（月上限10,000円）、まかない（1日1食）あり\n・応募方法：電話で面接の予約をし、履歴書を持って来店\n・面接日：毎週水曜日　15:00〜17:00"},
    {"t": "reading", "s": "jouhou", "q": "ホールで、午後十時から十一時まで働く一時間の時給はいくらですか。", "o": ["1,100円", "1,375円", "1,250円", "1,500円"], "a": 1, "x": "Setelah pukul 22 naik 25%: 1.100 x 1,25 = 1.375 yen. 1.500 yen adalah hitungan untuk dapur.", "p": "【カフェ「ひだまり」スタッフ募集】\n・仕事内容：ホール（接客）／キッチン（調理補助）\n・時給：ホール　1,100円／キッチン　1,200円　※22時以降は25%増し\n・勤務時間：①8:00〜14:00　②12:00〜18:00　③17:00〜23:00（いずれも休憩あり）\n・勤務日：週2日以上（土日のどちらか1日は必ず入れる方）\n・応募条件：高校生は不可。キッチンは、調理の経験がある方のみ。\n・待遇：交通費（月上限10,000円）、まかない（1日1食）あり\n・応募方法：電話で面接の予約をし、履歴書を持って来店\n・面接日：毎週水曜日　15:00〜17:00"},
    {"t": "reading", "s": "jouhou", "q": "市内の団体が、三十名で午後一時から午後四時まで会議をします。プロジェクターも使いたい場合、料金の合計はいくらですか。", "o": ["2,300円", "3,500円", "3,000円", "5,000円"], "a": 1, "x": "30 orang: Ruang 2. 1.000 x 3 jam = 3.000 + proyektor 500 = 3.500 yen. Ruang 1 hanya 20 orang.", "p": "【中央市民センター　会議室のご利用案内】\n部屋／定員／1時間あたりの料金（市内団体／市外団体）\n第1会議室／20名／600円／900円\n第2会議室／40名／1,000円／1,500円\n大会議室／100名／2,400円／3,600円\n※利用時間は9:00〜21:00。1回の利用は最大4時間まで。\n※プロジェクターの貸し出しは1回500円（第1会議室には設置済みで無料）。\n※利用日の2か月前の1日から、窓口または電話で予約できます。（例：6月15日の利用は4月1日から）\n※利用日の3日前までにキャンセルすれば全額返金。それ以降は返金なし。"},
    {"t": "reading", "s": "jouhou", "q": "8月20日に会議室を使いたいとき、予約できるのはいつからですか。", "o": ["6月20日", "7月1日", "8月1日", "6月1日"], "a": 3, "x": "Dua bulan sebelum, tanggal 1: 20 Agustus -> mulai 1 Juni.", "p": "【中央市民センター　会議室のご利用案内】\n部屋／定員／1時間あたりの料金（市内団体／市外団体）\n第1会議室／20名／600円／900円\n第2会議室／40名／1,000円／1,500円\n大会議室／100名／2,400円／3,600円\n※利用時間は9:00〜21:00。1回の利用は最大4時間まで。\n※プロジェクターの貸し出しは1回500円（第1会議室には設置済みで無料）。\n※利用日の2か月前の1日から、窓口または電話で予約できます。（例：6月15日の利用は4月1日から）\n※利用日の3日前までにキャンセルすれば全額返金。それ以降は返金なし。"},
    {"t": "listen", "s": "kadai", "q": "山田さんは、このあと何をしますか。", "o": ["ホテルを変更する。", "取引先に訪問の時間をメールで知らせる。", "お土産を買う。", "資料を印刷する。"], "a": 1, "x": "Yamada diminta memberi tahu waktu kunjungan lewat email. Hotel diurus pembicara, oleh-oleh oleh Tanaka, materi sudah dicetak.", "say": "来週の出張の準備について確認します。新幹線のチケットは、もう取ってあります。ホテルは、駅から遠いところしか空いていなかったので、駅の近くのところに変更したほうがいいと思います。資料は、私がもう印刷しました。取引先に渡すお土産は、田中さんが買ってくれることになっています。そうですね、ホテルの変更は、私が今日中に電話します。山田さんは、先方に訪問の時間を、もう一度メールで知らせておいてください。"},
    {"t": "listen", "s": "kadai", "q": "客は、このあとどうしますか。", "o": ["会社の帰りに、駅前の店でMサイズを受け取る。", "ここでLサイズを買う。", "Mサイズを家に送ってもらう。", "Mサイズが入荷するまで待つ。"], "a": 0, "x": "Pelanggan memilih menitipkan (取り置き) di toko depan stasiun dan mengambilnya sepulang kerja.", "say": "すみません、このシャツのMサイズはありますか。申し訳ありません、Mサイズは今、在庫がないんです。そうですか。他の店舗にあるかどうか、調べましょうか。お願いします。お待たせしました。駅前の店に一枚あります。そちらに取り置きもできますし、ここへ送ることもできます。送ると三日かかります。駅前なら会社の帰りに寄れるので、そちらにします。取り置きをお願いします。"},
    {"t": "listen", "s": "kadai", "q": "学生は、レポートをどのように出しますか。", "o": ["メールで、PDFを送る。", "学習支援システムに、PDFで出す。", "オフィスアワーに、紙で持っていく。", "二十日までに、メールで出す。"], "a": 1, "x": "Pengumpulan lewat sistem pendukung belajar dalam bentuk PDF, bukan email; batas diundur ke tanggal 23.", "say": "レポートの提出について連絡します。提出期限は今月の二十日でしたが、来週、学内の行事があるため、二十三日の金曜日まで延ばします。提出は、これまでのようにメールではなく、学習支援システムからお願いします。ファイルは、PDFにしてください。参考文献のリストが入っていない人が去年は多かったので、忘れないようにしてください。質問があれば、オフィスアワーに来てください。"},
    {"t": "listen", "s": "kadai", "q": "この人は、このあと何をしますか。", "o": ["レンタカーを予約する。", "旅館に電話して予約する。", "今日の帰りに、駅で切符を買う。", "車の準備をする。"], "a": 2, "x": "Penginapan sudah dipesan; tinggal membeli tiket di stasiun sepulang kerja.", "say": "週末の旅行の計画を立てています。車だと、途中で渋滞に巻き込まれるかもしれません。電車は少し高いですが、乗り換えが一回だけで、のんびりできます。それに、旅館は駅まで迎えに来てくれるそうです。レンタカーを借りる手もありますが、運転する人が疲れてしまいます。今回は、運転の必要がない方法にします。旅館の予約は済んでいるので、あとは切符を買うだけです。今日の帰りに駅に寄って、買ってきます。"},
    {"t": "listen", "s": "kadai", "q": "三日たっても熱が下がらない場合、患者はどうしますか。", "o": ["もう一度、病院へ行く。", "粉薬を、朝と夜に飲む。", "薬局に薬を返しに行く。", "お酒を飲んで、様子を見る。"], "a": 0, "x": "Jika demam tidak turun setelah 3 hari, kembali ke rumah sakit.", "say": "お薬について説明します。この錠剤は、朝と夜の食後に一錠ずつ飲んでください。こちらの粉薬は、熱が三十八度以上ある時だけ、水に溶かして飲んでください。お酒を飲む日は、薬を飲まないでください。薬は五日分出しています。もし三日たっても熱が下がらない場合は、もう一度病院に来てください。気分が悪くなったら、すぐに薬局に電話をしてください。"},
    {"t": "listen", "s": "kadai", "q": "聞いている人は、まず何をしますか。", "o": ["参加者の名札を作る。", "業者に連絡する。", "机と椅子を並べる。", "椅子を百脚用意する。"], "a": 0, "x": "Lawan bicara diminta membuat tanda pengenal; kontak vendor dan menata meja kursi dilakukan pembicara.", "say": "明日のイベントの準備ですが、机は、参加者が八十人に減ったので、八十脚で大丈夫です。椅子は、足りなくなると困るので、予定どおり百脚用意しましょう。受付に置くパンフレットは、まだ届いていないんですよね。それは、私が業者に連絡して、今日中に届けてもらうよう頼みます。机と椅子は、私が並べますから、あなたは、受付に置く名札を作ってください。名簿は、このファイルに入っています。"},
    {"t": "listen", "s": "kadai", "q": "玉ねぎを炒めたあと、何をしますか。", "o": ["ルーを入れる。", "水で二十分煮る。", "野菜を切る。", "肉を入れる。"], "a": 3, "x": "Urutan: tumis bawang, masukkan daging, tambah air dan rebus 20 menit, roux setelah api dimatikan.", "say": "今日は、カレーを作ります。まず、野菜を洗って、切ります。じゃがいもは大きめに、にんじんは小さめに切ってください。玉ねぎは薄く切って、油で茶色になるまでよく炒めます。そこへ肉を入れて、色が変わったら、水を加えて二十分煮ます。ルーを入れるのは、火を止めてからです。熱いままだと溶けにくいので、気をつけてください。"},
    {"t": "listen", "s": "kadai", "q": "客は、どうしますか。", "o": ["S席を買って、カードで払う。", "A席を買って、コンビニで払う。", "S席を買って、コンビニで払う。", "A席を買って、カードで払う。"], "a": 3, "x": "S席 habis; pelanggan memilih A dan membayar dengan kartu karena tiket langsung bisa dilihat.", "say": "コンサートのチケットですね。S席は完売でして、A席のみ残っております。A席は一枚八千円です。お支払いは、コンビニでもカードでもできます。カードですと、すぐにメールでチケットが届きますが、コンビニでは、三日以内にお支払いいただかないと、予約が取り消しになります。わかりました。A席を二枚お願いします。すぐにチケットが見られる方法にしたいので、そちらで払います。"},
    {"t": "listen", "s": "kadai", "q": "この人は、このあと何をしますか。", "o": ["他の部署に、午前に移ってもらう。", "小さい会議室を予約する。", "取引先に、訪問を金曜日にできないかお願いする。", "木曜日の午前に会議を行う。"], "a": 2, "x": "Ia akan meminta klien memindahkan kunjungan ke Jumat siang, saat ruang besar tersedia.", "say": "来週の木曜の午後、取引先が来るので、大きい会議室を取りたかったのですが、他の部署がもう予約していました。相談したところ、その部署は午前に移ってもいいと言ってくれました。ところが、取引先は午前には来られないそうです。小さい会議室なら空いていますが、取引先は五人来るので、狭いかもしれません。結局、大きい会議室が使える金曜の午後に、訪問の日を変えてもらうよう、お願いすることにします。"},
    {"t": "listen", "s": "kadai", "q": "雨の日に市役所へ行くには、どうするとよいと言っていますか。", "o": ["北口を出て、交差点を右に曲がる。", "改札を出て左の地下道に入り、三番出口から出る。", "駅からバスに乗る。", "銀行の隣のビルに入る。"], "a": 1, "x": "Saat hujan: lewat terowongan bawah tanah di kiri gerbang tiket, keluar di pintu keluar no. 3.", "say": "市役所へは、駅の北口を出てまっすぐ行って、大きな交差点を右に曲がると、銀行の隣の隣に白いビルが見えます。それが市役所です。歩いて十分ほどです。でも、今日のように雨の日は、地下道を使うと濡れません。地下道は、改札を出てすぐ左にあります。そこを通って、出口三番から出ると、市役所の前に着きます。"},
    {"t": "listen", "s": "kadai", "q": "試合に出るために、部員はどうしなければなりませんか。", "o": ["先生にユニフォームを借りる。", "日程表に、保護者の署名をもらう。", "飲み物を用意する。", "日程表を作って配る。"], "a": 1, "x": "Tanpa tanda tangan wali pada jadwal pertandingan, tidak boleh ikut bertanding.", "say": "練習について説明します。明日は朝九時に、学校の体育館に集合です。ユニフォームは、洗濯が間に合わなかった人には予備を貸しますので、先生に言ってください。昼ご飯は各自で持ってきてください。飲み物は部で用意します。それから、試合の日程表を配ります。これを親に見せて、保護者の署名をもらってきてください。署名がないと、試合には出られません。"},
    {"t": "listen", "s": "kadai", "q": "客は、予約をどのように変更しましたか。", "o": ["泊まる日を三泊に延ばす。", "一泊目から四人用の部屋にする。", "人数だけ変えて、部屋は同じにする。", "二泊目だけ、四人用の部屋に移る。"], "a": 3, "x": "Tanggal 10 kamar 4 orang penuh; malam kedua (tanggal 11) pindah ke kamar 4 orang.", "say": "十日から二泊で予約している鈴木です。人数が三人から四人に増えたので、部屋を替えたいのですが。今の部屋は三人用ですね。四人用の部屋は、十日は満室ですが、十一日でしたら空いております。では、一泊目は今の部屋のままで、二泊目だけ四人用に移ることはできますか。可能です。ただ、荷物を移していただくことになります。それでお願いします。"},
    {"t": "listen", "s": "point", "q": "パン屋が人気なのは、何が一番の理由ですか。", "o": ["小麦粉が特別だから。", "値段が安いから。", "焼き上がりの時間を知らせていて、焼きたてが買えるから。", "店が駅の中にあるから。"], "a": 2, "x": "Alasan utama menurut pemilik: jam selesai panggang diumumkan sehingga pelanggan bisa membeli roti yang baru matang.", "say": "新しくできた駅前のパン屋は、毎日たくさんの客で混んでいます。そこのパンは、小麦粉が特別だとか、値段が安いとか言われますが、店長に聞いてみると、それだけではないそうです。人気の一番の理由は、焼き上がりの時間を店の外に張り出していることだそうです。客は、焼きたてのパンを買いたいので、その時間に合わせて来ます。そのため、いつも焼きたてを買うことができ、また来たいと思うのだそうです。"},
    {"t": "listen", "s": "point", "q": "この人が会社を辞めた一番の理由は何ですか。", "o": ["給料が少なかったから。", "上司との関係が悪かったから。", "仕事が大変すぎたから。", "同じ仕事の繰り返しで、成長を感じられなくなったから。"], "a": 3, "x": "Alasan: pekerjaan berulang, tidak merasa berkembang. Gaji dan hubungan kerja tidak bermasalah.", "say": "先月、五年間働いた会社を辞めました。給料に不満があったわけではありません。上司や同僚との関係もよかったです。ただ、毎日同じ仕事の繰り返しで、成長している実感がなくなってしまったのです。もっといろいろな経験をしたいと思い、小さな会社に移ることに決めました。そこでは、一人で幅広い仕事を任されるので大変ですが、毎日が新鮮です。"},
    {"t": "listen", "s": "point", "q": "この人が遅れたのは、なぜですか。", "o": ["電車が止まったから。", "鍵をなくしたから。", "鍵をかけたか確かめるために、家に戻ったから。", "家に忘れ物をしたから。"], "a": 2, "x": "Ia kembali ke rumah untuk memastikan pintu terkunci, sehingga ketinggalan kereta.", "say": "遅れてしまって、すみません。電車が止まったのですか。いえ、電車は動いていました。家を出てから、鍵をかけたかどうか心配になって、戻ったんです。確認したら、ちゃんとかかっていました。それで、一本あとの電車に乗ることになってしまいました。次からは、鍵をかけたら、写真を撮っておこうと思います。"},
    {"t": "listen", "s": "point", "q": "雨の日でも売上が伸びることがあるのは、なぜですか。", "o": ["雨の日に来た客に、コーヒーの割引をしているから。", "雨の日は、傘がよく売れるから。", "雨の日は、客が増えるのが普通だから。", "コーヒーを、いつも半額にしているから。"], "a": 0, "x": "Layanan kopi setengah harga khusus hari hujan menambah pengunjung.", "say": "雨の日は、客が少なくなるのが普通です。しかし、うちの店は、雨の日のほうが売上が伸びることがあります。それは、雨の日に来てくれた客に、コーヒーを半額にするサービスをしているからです。このサービスを始めてから、雨の日でも店に入ってくれる人が増えました。ただし、費用がかかるので、いつまで続けるかは考えているところです。"},
    {"t": "listen", "s": "point", "q": "この人が留学をやめたのは、なぜですか。", "o": ["学会で発表する機会があるから。", "お金が足りないから。", "語学に自信がないから。", "先生に留学を反対されたから。"], "a": 0, "x": "Ia diajak presentasi di konferensi tahun depan, kesempatan yang hanya datang sekali.", "say": "来年から留学する予定でしたが、行かないことにしました。お金の問題ではありません。奨学金がもらえることが決まっていましたから。語学が心配だったわけでもありません。実は、研究室の先生から、来年の学会で発表しないかと誘われたのです。留学すると、その準備ができなくなってしまいます。留学はまたいつでもできますが、この機会は今回だけだと思い、残ることにしました。"},
    {"t": "listen", "s": "point", "q": "この人が引っ越すのは、なぜですか。", "o": ["隣の部屋の音で、よく眠れないから。", "会社が遠いから。", "家賃が高いから。", "駅から遠くて不便だから。"], "a": 0, "x": "Alasan: suara dari kamar sebelah membuatnya sulit tidur.", "say": "家を引っ越すことになりました。会社が遠いからではありません。今の家は駅から近くて便利ですし、家賃も安いです。ただ、隣の部屋の音が気になって、夜によく眠れないんです。何度か管理会社に相談しましたが、状況は変わりませんでした。静かなところに移れば、睡眠も取れるし、仕事の調子もよくなると思います。"},
    {"t": "listen", "s": "point", "q": "客が掃除機を返品したい理由は何ですか。", "o": ["故障したから。", "吸う力が弱いから。", "子供が音を怖がるから。", "音が大きくて、夜に使えないから。"], "a": 3, "x": "Alasan: terlalu berisik sehingga tidak bisa dipakai malam hari.", "say": "先日買った掃除機を返品したいのですが。故障したわけではありません。吸う力も十分あります。ただ、使ってみたら、思ったより音が大きくて、夜は使えないことがわかりました。うちは小さい子供が早く寝るので、夜に掃除をすることが多いんです。もう少し静かな機種に交換していただけませんか。"},
    {"t": "listen", "s": "point", "q": "野菜がよく売れる一番の理由は何ですか。", "o": ["野菜が新鮮だから。", "食べ方を書いたカードを付けているから。", "値段を半分にしたから。", "珍しい野菜を作っているから。"], "a": 1, "x": "Kartu cara memasak membuat pembeli tenang membeli sayur yang tak dikenal.", "say": "うちの野菜が直売所でよく売れるのは、新鮮だからだと思われがちですが、それだけではありません。実は、野菜ごとに、おいしい食べ方を書いた小さなカードを付けているんです。使い道がわからない野菜は、なかなか買ってもらえませんが、カードがあれば、安心して買えます。始めた当初は手間がかかりましたが、売上が二倍になったので、今ではやめられません。"},
    {"t": "listen", "s": "point", "q": "この人がプロジェクトを断ったのは、なぜですか。", "o": ["仕事の内容に興味がないから。", "給料が下がるから。", "同僚に反対されたから。", "今のチームの仕事が終わっていないから。"], "a": 3, "x": "Pekerjaan tim saat ini belum selesai; keluar di tengah akan merepotkan rekan.", "say": "先週頼まれた新しいプロジェクトの話ですが、お断りすることにしました。仕事の内容には興味がありますし、給料も今より上がります。でも、今のチームの仕事が、まだ終わっていません。途中で抜けると、同僚に迷惑がかかります。それで、今回は見送ることにしました。"},
    {"t": "listen", "s": "point", "q": "この人がジョギングを続けている理由は何ですか。", "o": ["体重が減ったから。", "仕事の段取りが整理されるから。", "友人と走るのが楽しいから。", "会社が遠いので、体力が必要だから。"], "a": 1, "x": "Selama lari, urutan kerja hari itu tertata di kepala. Berat badan hampir tidak berubah.", "say": "私は、朝のジョギングを三年続けています。ダイエットのためだと思われますが、体重はあまり変わっていません。続けている理由は、走っている間に、その日の仕事の段取りが頭の中で整理されるからです。会社に着いた時には、何から始めればいいかが決まっているので、仕事が早く進みます。"},
    {"t": "listen", "s": "point", "q": "動物園の来園者が増えたのは、なぜですか。", "o": ["新しい動物が来たから。", "入園料が安くなったから。", "子供向けのイベントが増えたから。", "飼育員のガイドタイムが人気だから。"], "a": 3, "x": "Yang berubah hanya dimulainya 'guide time' oleh perawat hewan.", "say": "市の動物園では、去年から来園者が増え続けています。新しい動物が来たからでしょうか。いえ、動物は去年とほとんど変わっていません。変わったのは、飼育員が動物について話す「ガイドタイム」が始まったことです。動物の習性や性格を、飼育員が自分の言葉で話すので、子供だけでなく大人にも人気です。そのため、また来たいと感じる人が多いのです。"},
    {"t": "listen", "s": "point", "q": "電車が遅れた原因は何ですか。", "o": ["事故があったから。", "駅で、客が降りるのに時間がかかったから。", "天気が悪かったから。", "客がドアを押さえていたから。"], "a": 1, "x": "Penumpang dengan barang besar lama turun sehingga pintu terlambat tertutup.", "say": "今朝は、電車が十五分遅れました。事故ではなく、天気のせいでもありません。ある駅で、大きな荷物を持った客が降りるのに時間がかかり、ドアが閉まるのが遅れたそうです。そのあとの電車も、前の電車に続いて遅れが広がりました。ラッシュの時間は、一つの小さな遅れが全体に影響しやすいので、降りる人が先に降りてから乗るなど、協力が必要だとアナウンスがありました。"},
    {"t": "listen", "s": "gaiyou", "q": "この話の内容として、合っているものはどれですか。", "o": ["歩数より、少し速く歩くことのほうが大切だ。", "健康のためには、一日一万歩が必要だ。", "歩数が多いほど、足が強くなる。", "歩くことは、体によくない。"], "a": 0, "x": "Dokter: tidak perlu 10.000 langkah; yang penting ada waktu berjalan agak cepat.", "say": "最近、健康のために歩く人が増えています。しかし、ただ歩けばいいというわけではありません。ある医師によると、一日に一万歩も歩く必要はなく、七千歩ほどでも十分に効果があるそうです。むしろ、無理に歩数を増やそうとして足を痛めてしまう人もいます。それよりも、少し速く歩く時間を作ることが大切だと言います。"},
    {"t": "listen", "s": "gaiyou", "q": "この会社のノー会議デーについて、正しいものはどれですか。", "o": ["連絡が取れず、仕事が遅れた。", "問題は少なく、他の日の会議も短くなった。", "金曜日は、社員が休みを取れる。", "会議の数が、全体で増えた。"], "a": 1, "x": "Hampir tanpa masalah dan rapat di hari lain jadi lebih singkat.", "say": "私の会社では、毎週金曜日に「ノー会議デー」を設けています。この日は会議を一切入れないことになっているので、社員は自分の仕事に集中できます。始める前は、連絡が取りにくくなって不便ではないかという心配もありました。しかし、実際には、急ぎの用はチャットで済ませることが多く、問題はほとんどありませんでした。むしろ、他の日の会議も短くなったという効果もありました。"},
    {"t": "listen", "s": "gaiyou", "q": "この話の内容として、合っているものはどれですか。", "o": ["すべての店が、値引きをやめた。", "食品ロスを減らすため値引きする店が増えたが、心配する店もある。", "値引きによって、定価で買う人が増えた。", "賞味期限が過ぎた商品を安く売る店が増えた。"], "a": 1, "x": "Diskon barang mendekati kedaluwarsa menambah, namun sebagian toko khawatir pembeli harga normal berkurang.", "say": "日本のコンビニでは、弁当やおにぎりなどの賞味期限が近づくと、値引きして売ることが増えています。以前は、期限が来ると捨てていましたが、食品ロスが問題になり、考え方が変わってきたのです。値引きした商品は、夕方から夜にかけてよく売れます。店にとっても、捨てる量が減って、処理の費用が安くなる利点があります。ただ、値引きをすると定価で買う人が減るのではないかと、心配する店もあります。"},
    {"t": "listen", "s": "gaiyou", "q": "学長が新入生に一番伝えたかったことは何ですか。", "o": ["自分で考え、疑問を見つけることを大切にしてほしい。", "先生の話を、そのまま覚えてほしい。", "先生に質問するのは、迷惑になるのでやめてほしい。", "答えを、できるだけ早く見つけてほしい。"], "a": 0, "x": "Inti: universitas adalah tempat menemukan pertanyaan; pikirkan sendiri dan jangan ragu bertanya.", "say": "大学の入学式で、学長が新入生にあいさつをしました。学長は、「大学は、答えを教えてもらう場所ではなく、問いを見つける場所です」と述べました。授業で聞いたことをそのまま覚えるのではなく、なぜそうなのかを自分で考えてほしいと言いました。そして、わからないことがあったら、遠慮せずに先生に質問するようにとも話しました。"},
    {"t": "listen", "s": "gaiyou", "q": "この話の内容として、正しいものはどれですか。", "o": ["自転車通勤が減り、事故も減った。", "ヘルメットを着ける人は、すでに半分を超えた。", "市は、自転車での通勤を禁止しようとしている。", "自転車通勤が増え、市はヘルメットの着用と駐輪場の整備を進めようとしている。"], "a": 3, "x": "Pesepeda komuter bertambah; kota mendorong helm (baru 30%) dan membangun tempat parkir sepeda.", "say": "最近、自転車で通勤する人が増えているそうです。電車の混雑を避けられることや、運動になることが理由です。一方で、事故も増えているため、市では、ヘルメットを着けるよう呼びかけています。着用する人は、まだ全体の三割ほどですが、市は、来年までに半分以上にしたいと考えています。また、駐輪場の数が足りないという問題もあり、新しい駐輪場の建設も進めるとのことです。"},
    {"t": "listen", "s": "gaiyou", "q": "専門家の考えに合うものはどれですか。", "o": ["毎日必ず、全員でそろって食べるべきだ。", "家族で食事をしても、子供の満足度は変わらない。", "毎日でなくても、家族で食べる機会を作ることが大切だ。", "習い事をやめて、食事の時間を増やすべきだ。"], "a": 2, "x": "Pakar: tidak harus setiap hari, tetapi beberapa kali seminggu makan bersama itu penting.", "say": "昔は、家族みんなで夕食を食べるのが当たり前でしたが、今は、仕事や習い事の時間が違うため、そろって食べる家庭は少なくなりました。ある調査では、家族で食事をする回数が多い子供ほど、学校生活に満足していると感じる割合が高いという結果が出ています。もちろん、毎日は難しくても、週に何回かでも、一緒に食べる時間を作ることが大切だと、専門家は話しています。"},
    {"t": "listen", "s": "gaiyou", "q": "この話の内容として、合っているものはどれですか。", "o": ["座席が狭くなり、座れる人数が増えた。", "座席の幅は変わらず、好評である。", "座りやすくなったが、座れる人数が減ったので、混雑時の対応を考えている。", "すべての車両で、座席が少なくなった。"], "a": 2, "x": "Kursi lebih lebar dan nyaman, tetapi jumlah penumpang duduk berkurang; perusahaan mempertimbangkan solusi jam sibuk.", "say": "新しい電車の座席が導入されました。以前の座席に比べて少し幅が広く、座りやすいと好評です。ただし、座席が広がった分、一両に座れる人数は、六人ほど減りました。会社は、混雑がひどい時間帯には、立つ人が増えて不便になるかもしれないと認めています。そのため、朝の混雑する時間は、座席の少ない別の車両を走らせることも検討しています。"},
    {"t": "listen", "s": "gaiyou", "q": "この人の話の内容として、合っているものはどれですか。", "o": ["現地の料理がおいしくて、日本のご飯を忘れた。", "日本料理が作れず、結局一人で食べていた。", "友達の国の料理は、口に合わなかった。", "食事に苦労したが、友達と料理をすることで楽しみに変わった。"], "a": 3, "x": "Awalnya sulit menyesuaikan makanan, tetapi memasak bersama teman membuat makan jadi menyenangkan.", "say": "私は、留学していた時、現地の料理に慣れるのに苦労しました。毎日、パンとチーズばかりで、日本のご飯が恋しくなりました。そこで、友達と一緒に、週に一度、日本料理を作る日を始めたのです。最初は、材料が手に入らなくて失敗ばかりでしたが、代わりのものを探すうちに、友達の国の料理も教えてもらえるようになり、むしろ食事が楽しみになりました。"},
    {"t": "listen", "s": "gaiyou", "q": "この話の内容として、正しいものはどれですか。", "o": ["すべての駅で、一斉に新しい表示を始めた。", "線をなくして、人の自由に任せることにした。", "ホームの表示を分かりやすくして混乱を減らす試みを、三つの駅で始めた。", "乗る人専用のホームを増やした。"], "a": 2, "x": "Penanda lantai peron dibuat lebih jelas, diuji di tiga stasiun dulu.", "say": "駅のホームで、電車を待つ人の列が乱れる問題について、鉄道会社が新しい試みを始めました。ホームの床に、矢印と乗車位置の線を、大きく描いたのです。これまでも線はありましたが、小さくて見えにくいという声がありました。新しい表示では、降りる人が通る道も示されているので、乗る人と降りる人がぶつかることが少なくなりました。まず三つの駅で始め、効果を見て広げていくそうです。"},
    {"t": "listen", "s": "gaiyou", "q": "この話の主な内容は何ですか。", "o": ["外食が増えて、冷凍食品が売れなくなった。", "冷凍食品の会社が、外食産業に参入した。", "外食の値段が下がり、客が戻ってきた。", "外食が減る中で冷凍食品が伸び、外食側も特別な体験で客を呼び戻そうとしている。"], "a": 3, "x": "Makan di luar menurun, makanan beku naik, restoran berusaha menarik pelanggan dengan pengalaman istimewa.", "say": "最近、外食をする人が減っていると言われます。値段が上がったことが大きな理由ですが、家で簡単においしく食べられる冷凍食品が良くなったことも影響しているそうです。ある冷凍食品の会社では、有名な店と共同で、本格的な味の商品を開発し、売上が大きく伸びました。外食産業の側も、家では食べられない特別な体験を提供して、客を呼び戻そうとしています。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["ええ、いいですよ。どのくらい必要ですか。", "はい、どういたしまして。", "すみません、失礼しました。", "それはよかったですね。"], "a": 0, "x": "Permintaan bantuan dijawab dengan persetujuan. 'どういたしまして' adalah balasan terima kasih.", "say": "資料のコピーを、手伝っていただけませんか。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["もちろん、昨日できました。", "そうですね、昨日はお休みでした。", "はい、明日までにお渡ししました。", "ちょっと厳しいかもしれませんが、やってみます。"], "a": 3, "x": "Pertanyaan tentang kemungkinan besok; jawaban lain memakai waktu lampau.", "say": "この仕事、明日までにできそうかな。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["ごちそうさまでした。", "もう少し考えたいので、あとでもいいですか。", "いらっしゃいませ、何名様ですか。", "お待たせしました、こちらです。"], "a": 1, "x": "Pelanggan menjawab pelayan; 'ごちそうさま' diucapkan setelah makan.", "say": "ご注文は、お決まりでしょうか。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["そうですか、おめでとうございます。", "どうぞ、お先に失礼します。", "はい、確かにお預かりします。", "いえ、まだ時間はありますから、気にしないでください。"], "a": 3, "x": "Menanggapi permintaan maaf karena terlambat dengan 'tidak apa-apa'.", "say": "遅くなって、申し訳ありません。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["ありがとうございます、いただきます。", "面白いと思いますが、費用が少し気になります。", "それは大変でしたね、お大事に。", "どういたしまして、またどうぞ。"], "a": 1, "x": "Diminta pendapat, maka beri pendapat.", "say": "この企画について、どう思いますか。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["はい、行ってきます。", "まだ決めてないんだ。家でのんびりするかも。", "ええ、どうぞ行ってください。", "行ったことがありますよ、昨日。"], "a": 1, "x": "Menjawab rencana libur; '行ってきます' dipakai saat berangkat.", "say": "今度の連休、どこか行くの？"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["はい、いってきました。", "あ、もうそんな時間ですか。すぐ行きます。", "いえ、始めたのは私ではありません。", "会議は終わって、よかったです。"], "a": 1, "x": "Pengingat rapat dibalas dengan bergegas.", "say": "そろそろ、会議が始まりますよ。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["先週の金曜日に、お知らせしました。", "お知らせいただき、ありがとうございました。", "いいえ、よろしくお願いします、さようなら。", "では、来週の水曜日はいかがでしょうか。"], "a": 3, "x": "Diminta hari yang cocok, usulkan hari.", "say": "ご都合のよい日を、お知らせください。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["すみません、お借りしました。", "いえいえ、お役に立ててよかったです。", "いいえ、これからお借りします。", "ええ、貸してもらってもいいですか。"], "a": 1, "x": "Meminjamkan buku lalu diberi terima kasih: jawab 'senang bisa membantu'.", "say": "この間お借りした本、ありがとうございました。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["はい、結構です。", "いえ、まだ食べていません。", "ええ、お元気でしたか。", "はい、ごめんください。"], "a": 0, "x": "Menjawab konfirmasi tempat duduk dengan 'はい、結構です'.", "say": "お客様、こちらのお席でよろしいでしょうか。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["ありがとう、助かりました。", "よかったですね、おめでとうございます。", "わかりました、お邪魔します。", "ええ、ぜひお直しください、私が。"], "a": 0, "x": "Terima kasih atas perbaikan yang sudah dilakukan.", "say": "資料に誤りがあったので、直しておきました。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["ええ、先ほどお尋ねしました。", "この道をまっすぐ行って、二つ目の角を左です。", "郵便局は、昨日行きました。", "はい、お尋ねしました、ありがとう。"], "a": 1, "x": "Menanyakan arah dijawab dengan petunjuk jalan.", "say": "ちょっとお尋ねしますが、郵便局はどこですか。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["はい、ごめんなさい、帰ってはいけません。", "ありがとうございます。それでは、お言葉に甘えて。", "いえ、お待たせしました。", "そうですか、いただきます。"], "a": 1, "x": "'お言葉に甘えて' = menerima tawaran baik dengan terima kasih.", "say": "今日は、早く帰ってもいいですよ。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["はい、新しくなりました。", "いいえ、どういたしまして。", "ええ、部署に行ってきます。", "ええ、おかげさまで、だいぶ慣れました。"], "a": 3, "x": "Menjawab 'sudah terbiasa belum?'.", "say": "新しい部署は、どう？もう慣れた？"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["それはよかったですね。", "どうぞ、お忘れなく。", "ええ、忘れてくれてありがとう。", "じゃあ、私のを貸しましょうか。"], "a": 3, "x": "Menawarkan pinjaman payung adalah tanggapan wajar.", "say": "うっかり、傘を忘れてきちゃった。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["はい、あとはスライドを仕上げるだけです。", "いえ、発表はお聞きしました。", "はい、準備をしていらっしゃいます。", "そうですね、おなかがいっぱいです。"], "a": 0, "x": "'していらっしゃいます' adalah bentuk hormat untuk orang lain, tidak untuk diri sendiri.", "say": "来週の発表、準備は進んでる？"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["いえ、どういたしまして。", "ええ、確認いただいたのでけっこうです。", "それなら、お届けいたしました。", "お手数ですが、よろしくお願いします。"], "a": 3, "x": "Menanggapi pihak yang akan memeriksa: 'お手数ですが、よろしくお願いします'.", "say": "ご注文の品が本日中に届けられるか、確認いたします。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["うん、天気もよくて、最高だったよ。", "いいえ、楽しんでください。", "ううん、旅行に行くつもりだよ。", "うん、楽しみにしているよ。"], "a": 0, "x": "Pertanyaan tentang perjalanan yang sudah lewat; jawaban lain bentuk masa depan/perintah.", "say": "この前の旅行、楽しかった？"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["それは座ってよかったです。", "ええ、どうぞ。", "ここは、おいしいですか。", "はい、おじゃまします。"], "a": 1, "x": "Izin duduk dijawab 'silakan'.", "say": "すみません、ここ、座ってもよろしいですか。"},
    {"t": "listen", "s": "sokuji", "q": "この発話に対する、いちばんよい返事を選んでください。", "o": ["ええ、わかりにくくて、すみません。", "ええ、いただきます、おいしそうですね。", "それでは、お先に失礼します。", "あなたの説明は、聞こえませんでした。"], "a": 0, "x": "Diminta menjelaskan ulang, setuju sambil minta maaf karena kurang jelas.", "say": "先ほどの件ですが、もう一度説明していただけますか。"},
    {"t": "listen", "s": "ltougou", "q": "三人は、どこに行くことにしましたか。", "o": ["新幹線で行ける海の町。", "去年と同じ温泉。", "山の自然の中。", "車で五時間かかる海の町。"], "a": 0, "x": "Onsen ditolak karena sudah dikunjungi tahun lalu; kota pantai yang bisa dicapai dengan shinkansen dipilih.", "say": "旅行先を決めましょう。私は温泉に行きたいな。疲れを取りたいから。でも、温泉は去年も行ったよね。今年は、海の近くの町で、おいしい魚を食べたいな。私は山で歩くのが好きだけど、今回は二人の意見に合わせるよ。海の町は遠いから、車だと五時間かかるよ。温泉なら、近くにもあるけどね。温泉は去年行ったから、今回はやめよう。海の町は遠いけど、新幹線で行ける町があるから、そこにしよう。"},
    {"t": "listen", "s": "ltougou", "q": "新商品の名前は、何に決まりましたか。", "o": ["ふわり", "ぽかぽか", "新しい名前を、考え直す。", "ほっと"], "a": 3, "x": "A mirip merek lain, B terlalu bernuansa musim dingin; C cocok sepanjang tahun dan unik.", "say": "新商品の名前を決めましょう。A案は「ふわり」、B案は「ぽかぽか」、C案は「ほっと」です。私はA案がいいと思います。柔らかさが伝わりますから。でも、それは他の会社の商品名に似ていませんか。確かに、少し似ていますね。B案は、温かさがよく伝わりますが、冬の商品だという印象が強すぎて、一年中売りにくいかもしれません。C案なら、季節を問わずに使えますし、他社の名前とも似ていません。では、C案に決めましょう。"},
    {"t": "listen", "s": "ltougou", "q": "この人は、どうすることにしましたか。", "o": ["駅から遠くて家賃が安い部屋を借り、自転車を買う。", "駅から近い部屋を借りる。", "安い部屋を借りるが、自転車は買わない。", "どちらの部屋も借りない。"], "a": 0, "x": "Memilih kamar murah (jauh dari stasiun) dan membeli sepeda dengan uang yang dihemat.", "say": "引っ越し先を決めたいんだけど、二つの部屋で迷っているんだ。一つは駅から五分で、家賃が八万円。もう一つは、駅から十五分で、家賃が六万円。広さは同じなんだ。駅から近いほうが便利だけど、毎月二万円の差は大きいよね。でも、毎日の通勤を考えると、十分の差は、一年だとかなりの時間になるよ。確かにそうだけど、浮いたお金で自転車を買えば、通勤の時間も短くなるんじゃない？それもそうだね。じゃあ、安いほうにして、自転車を買うことにするよ。"},
    {"t": "listen", "s": "ltougou", "q": "最終的に決まったテーマは何ですか。", "o": ["地方の人口減少だけを扱うテーマ。", "外国人観光客の増加だけを扱うテーマ。", "観光の面から見た、地方の人口減少。", "資料の多いテーマを、すべて合わせたもの。"], "a": 2, "x": "Kedua usulan digabung: penurunan penduduk daerah ditinjau dari sisi pariwisata.", "say": "卒論のテーマについて話しましょう。私は、地方の人口減少について書きたいです。資料も多いので、書きやすいと思います。私は、外国人観光客の増加がいいと思います。今、話題ですから、新しい視点が出せるかもしれません。でも、資料が多いテーマは、みんなが書くから、差がつきにくいですよね。そこで、人口減少を、観光の面から見るのはどうでしょうか。確かに、それなら新しい視点にもなるし、資料も使えます。それで進めてみましょう。"},
    {"t": "listen", "s": "ltougou", "q": "発表会は、どのように行うことになりましたか。", "o": ["グループで発表するだけにする。", "個人で、長く発表する。", "グループで発表し、そのあと一人ずつ質問に答える。", "個人で発表し、そのあとグループで質問に答える。"], "a": 2, "x": "Kompromi: presentasi kelompok lalu tanya jawab singkat per individu.", "say": "来月の発表会ですが、グループで発表するか、個人で発表するか、どちらがいいでしょうか。グループだと、準備の負担が分けられますが、一人ひとりの成績が分かりにくくなります。個人なら、頑張りがよく伝わりますが、人数が多いので、時間が足りなくなります。そうですね。では、グループで発表してもらって、そのあとで、一人ずつ短い質問に答えてもらいましょう。それなら、時間も足りますし、個人の理解も確認できます。"},
    {"t": "listen", "s": "ltougou", "q": "二人は、昼食をどうしますか。", "o": ["新しいイタリアンに行く。", "会社の隣のそば屋に行く。", "お弁当を買って、公園で食べる。", "会社の中で食べる。"], "a": 2, "x": "Restoran Italia harus antre, soba membosankan; mereka sepakat membeli bento dan makan di taman.", "say": "昼ご飯、どこにする？私は、新しくできたイタリアンに行ってみたいな。でも、あそこは並ぶって聞いたよ。昼休みは一時間しかないから、並ぶのは厳しいよね。じゃあ、会社の隣のそば屋はどう？早いし安いけど、毎週行ってるよね。確かに、ちょっと飽きたかな。だったら、お弁当を買って、公園で食べるのはどう？今日は天気もいいし。いいね、それなら時間もかからないし、気分も変わるね。"}
); })();
